from typing import List
shard_range_per_job = []

if num_shards <= max_num_jobs:
    for i in range(num_shards):
        shard_range_per_job.append(range(i, i+1))
else:
    shards_per_job = num_shards // max_num_jobs
    remainder = num_shards % max_num_jobs
    start = 0
    for i in range(max_num_jobs):
        end = start + shards_per_job
        if i < remainder:
            end += 1
        shard_range_per_job.append(range(start, end))
        start = end

return shard_range_per_job

