import pymongo
import logging
def wrapper(*args, **kwargs):
    retry_count = 0
    while True:
        try:
            return f(*args, **kwargs)
        except (pymongo.errors.AutoReconnect, pymongo.errors.OperationFailure) as e:
            if 'arctic' in f.__module__:
                logging.error(f"Caught exception in {f.__name__}: {e}")
            retry_count += 1
            if retry_count > 3:
                raise
            time.sleep(1)
return wrapper

