import pkg_resources
plugins_list = []
for entry_point in pkg_resources.iter_entry_points('myapp.plugins'):
    plugin_dict = {'name': entry_point.name, 'hooks': []}
    plugin = entry_point.load()
    for hook in plugin.get_hooks():
        plugin_dict['hooks'].append(hook)
    dist = pkg_resources.get_distribution(entry_point.dist.key)
    if dist:
        plugin_dict['version'] = dist.version
        plugin_dict['project_name'] = dist.project_name
    plugins_list.append(plugin_dict)
return plugins_list

