class RsyncCommand:
    def __init__(self, src, dest, flags):
        self.src = src
        self.dest = dest
        self.flags = flags

    def execute(self):
        command = ["rsync"] + self.flags + [self.src, self.dest]
        process = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        output, error = process.communicate()
        if process.returncode != 0:
            raise Exception(f"rsync command failed with error: {error.decode('utf-8')}")
        return output.decode('utf-8')

return RsyncCommand(src, dest, flags)

