from functools import wraps
def decorator(func: Callable) -> Callable:
    @wraps(func)
    def new_func(*args, **kwargs):
        warnings.warn(f"Call to deprecated function {func.__name__}. Reason: {reason}", category=DeprecationWarning, stacklevel=2)
        return func(*args, **kwargs)
    return new_func
return decorator

