            raise ValueError("Circular dependency detected")
        order_list.extend(sorted(independent_nodes))
        graph = {name: deps - independent_nodes for name, deps in graph.items() if name not in independent_nodes}
    order_lists.append(order_list)

# Choose the order with the fewest conflicts
chosen_order = min(order_lists, key=lambda x: sum(1 for name in x if name in conflicts))

# Return the chosen order along with the corresponding recipes, python modules, and bootstrap instance
return chosen_order, [ctx.recipes[name] for name in chosen_order], [ctx.recipe_modules[name] for name in chosen_order], bs

