from collections import Counter
import pandas as pd
def compute_likelihood(session: str, window_length: int) -> float:
    likelihood = 0.0
    for i in range(len(session) - window_length + 1):
        window = session[i:i+window_length]
        window_count = Counter(window)
        rarest_count = min(window_count.values())
        likelihood += rarest_count / window_length
    return likelihood / (len(session) - window_length + 1)

data['likelihood'] = data[session_column].apply(
    lambda session: compute_likelihood(session, window_length)
)

data['rarest_window'] = data[session_column].apply(
    lambda session: min(
        (session[i:i+window_length] for i in range(len(session) - window_length + 1)),
        key=lambda window: sum(window.count(c) for c in set(window))
    )
)

return data

