from typing import List
weights = [2, 4, 8, 5, 0, 9, 7, 3, 6, 1, 2, 4, 8]
if len(digits) != len(weights):
    raise ValueError("Length of digits should be equal to length of weights")

weighted_sum = sum(digit * weight for digit, weight in zip(digits, weights))
control_digit = 11 - (weighted_sum % 11)
if control_digit == 10:
    return 0
elif control_digit == 11:
    return 0
else:
    return control_digit

from typing import List
