keywords = ['SELECT', 'INSERT', 'UPDATE', 'DELETE', 'FROM', 'WHERE', 'ORDER BY', 'GROUP BY', 'HAVING', 'JOIN', 'LEFT JOIN', 'RIGHT JOIN', 'INNER JOIN', 'OUTER JOIN', 'ON', 'AND', 'OR', 'NOT', 'IN', 'BETWEEN', 'LIKE', 'IS NULL', 'IS NOT NULL', 'UNION', 'ALL', 'AS', 'DISTINCT', 'COUNT', 'MAX', 'MIN', 'AVG', 'SUM', 'CASE', 'WHEN', 'THEN', 'ELSE', 'END', 'LIMIT']

