last_keyword = None
for keyword in keywords:
    match = re.search(rf'\b{keyword}\b', sql, re.IGNORECASE)
    if match:
        last_keyword = match.group()

# If a keyword is found, strip the SQL statement after the last keyword
if last_keyword:
    last_keyword_index = match.end()
