from mopidy import ext
extensions = []
for entry_point in ext.Extension.ext_points():
    try:
        extension_class = entry_point.load()
        if issubclass(extension_class, ext.Extension):
            extension_data = ExtensionData(
                name=extension_class.ext_name,
                version=extension_class.ext_version,
                description=extension_class.ext_description,
                extension_class=extension_class
            )
            extensions.append(extension_data)
    except Exception as e:
        print(f"Error loading extension: {entry_point.name}: {e}")
return extensions

